<script setup lang="ts">import{ref,onMounted,computed}from'vue';import{CalendarDays}from'lucide-vue-next';import{http}from'@/shared/api/httpClient';const items=ref<any[]>([]);onMounted(async()=>items.value=(await http.get('/ventas/proximas-entregas')).data);const totalM2=computed(()=>items.value.reduce((sum,x)=>sum+x.cantidadM2,0));function timing(days:number){return days<0?`Atrasada ${Math.abs(days)} días`:days===0?'Entrega hoy':days===1?'Mañana':`En ${days} días`}</script>
<template><section class="page"><div class="page-title"><div><h2>Próximas entregas</h2><p>Agenda rápida de ventas futuras y metros comprometidos.</p></div></div><div class="grid delivery-metrics"><article class="card metric"><small>Entregas pendientes</small><strong>{{items.length}}</strong><em>Operaciones programadas</em></article><article class="card metric"><small>Superficie comprometida</small><strong>{{totalM2}} m²</strong><em>Para planificación y logística</em></article></div><div class="delivery-list"><article v-for="item in items" :key="item.id" class="card delivery-card"><div class="delivery-date"><CalendarDays/><div><small>FECHA ESTIMADA</small><strong>{{new Date(item.fechaEntregaEstimada+'T00:00:00').toLocaleDateString('es-AR',{day:'2-digit',month:'long',year:'numeric'})}}</strong></div></div><span class="badge" :class="{warn:item.diasRestantes<=3}">{{timing(item.diasRestantes)}}</span><div class="delivery-info"><div><small>Cliente</small><b>{{item.cliente}}</b></div><div><small>Producto</small><b>{{item.tipoCesped}}</b></div><div><small>Superficie</small><b>{{item.cantidadM2}} m²</b></div></div><p v-if="item.observaciones" class="delivery-note">{{item.observaciones}}</p></article><div v-if="!items.length" class="panel empty">No hay entregas futuras programadas.</div></div></section></template>
